"use client";
import {useEffect,useState} from "react";import {useParams,useRouter} from "next/navigation";import PageTitle from "@/composants/ui/PageTitle";import Section from "@/composants/ui/Section";import Loading from "@/composants/ui/Loading";import Alert from "@/composants/ui/Alert";import {serviceAdministration} from "@/services/ServiceAdministration.js";
export default function Page(){const {id}=useParams();const router=useRouter();const [u,setU]=useState(null);const [feedback,setFeedback]=useState(null);const [loading,setLoading]=useState(true);useEffect(()=>{serviceAdministration.getUser(id).then(setU).catch(e=>setFeedback({type:"error",message:e.message})).finally(()=>setLoading(false));},[id]);async function toggle(){try{setU(await serviceAdministration.setStatus(id,u.statutCompte==='actif'?'suspendu':'actif'));}catch(e){setFeedback({type:"error",message:e.message});}}if(loading)return <Loading message="Chargement…"/>;if(!u)return <Alert type="error" message="Commerce introuvable."/>;const p=u.profile||{};return <div className="space-y-8"><PageTitle title={u.name} description="Détails du compte commerçant."/>{feedback&&<Alert type={feedback.type} message={feedback.message}/>}<Section title="Informations"><Info l="Email" v={u.email}/><Info l="Ville" v={p.ville}/><Info l="Département" v={p.departement}/><Info l="Adresse" v={p.adresse}/><Info l="Téléphone" v={p.telephone}/><Info l="Statut" v={u.statutCompte}/></Section><div className="flex gap-3"><button onClick={()=>router.back()} className="rounded-lg bg-slate-100 px-5 py-3">Retour</button>{u.statutCompte!=='invite'&&<button onClick={toggle} className="rounded-lg bg-indigo-600 px-5 py-3">{u.statutCompte==='actif'?"Suspendre":"Réactiver"}</button>}</div></div>}
function Info({l,v}){return <p className="py-2 text-sm text-slate-700"><strong>{l} :</strong> {v||"—"}</p>}
